import { Table, ReferenceColumn, StringColumn, DomainPathColumn, GenericColumn, DomainIdColumn } from '../../db'

export const sys_hub_flow_block = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: false,
    },
    display: 'name',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Flow Block',
    name: 'sys_hub_flow_block',
    schema: {
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Sys overrides',
            referenceTable: 'sys_hub_flow_block',
        }),
        label_cache: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Label Cache',
            maxLength: 8000,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Name',
            mandatory: true,
            maxLength: 255,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the context belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
    },
})
